"""
Top-level package metadata.

Public API
----------
- ``__version__``: The application/library version.

Notes
-----
- API versioning (e.g., "v1") is owned by `your_service_name.utils.versioning`.
"""

from __future__ import annotations

from typing import TYPE_CHECKING

__all__ = ["__version__"]
__version__: str

if TYPE_CHECKING:
    # Let mypy know a symbol exists at build/install time, but do not import at runtime here.
    # _version.py is generated by setuptools_scm, so ignore import-not-found in source checkouts.
    from ._version import version as __version__

else:
    # 1) Prefer the generated version (when present in sdist/wheel)
    try:  # pragma: no cover - trivial import
        from ._version import version as __version__
    except (ImportError, AttributeError):
        # 2) Otherwise, resolve version from installed package metadata
        from importlib.metadata import PackageNotFoundError
        from importlib.metadata import version as _pkg_version

        try:
            __version__ = _pkg_version("your_service_name")
        except PackageNotFoundError:
            # 3) Dev fallback: source tree without generated version file or install
            __version__ = "0.0.0"
